import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.CHeM0PsO.js";const i="/img/emotion.jpg",c=JSON.parse('{"title":"心态","description":"","frontmatter":{},"headers":[],"relativePath":"interview/xintai.md","filePath":"interview/xintai.md","lastUpdated":null}'),o={name:"interview/xintai.md"};function E(l,e,p,h,d,B){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="心态" tabindex="-1">心态 <a class="header-anchor" href="#心态" aria-label="Permalink to &quot;心态&quot;">​</a></h1><h2 id="低姿态不能换来成功-1" tabindex="-1">低姿态不能换来成功 <a href="https://weread.qq.com/web/reader/46532b707210fc4f465d044k182326e0221182be0c5ca23" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#低姿态不能换来成功-1" aria-label="Permalink to &quot;低姿态不能换来成功 [1]&quot;">​</a></h2><p>情绪图：</p><p><img src="'+i+'" alt="emotion"></p><h3 id="在商业公司中很少有学徒制" tabindex="-1">在商业公司中很少有学徒制 <a class="header-anchor" href="#在商业公司中很少有学徒制" aria-label="Permalink to &quot;在商业公司中很少有学徒制&quot;">​</a></h3><p>其实能够看得出来，不管你摆出什么样的低姿态，你的潜台词就是“请相信我一次吧，我愿意学，请给我一次机会吧”“我可以不要工资，等我学会了你再给我工资”。这表示你不够成熟，并没有感受到商业社会的激烈竞争。在古代，你可以上山学艺或者跪拜求师，但是现在社会发展这么快，每家公司都要努力赢利才能生存下去，单凭你摆出一个低姿态就决定录用你是不可能的。没有经验不要紧，不一定要用低姿态去乞求别人，</p><p>你可以展示出你的潜力、你的创造力、你的创新力，哪怕只展示出比别人勤奋也可以。比如，你喜欢某个公司的职位，而其他人可能只大概了解这个公司是做什么的、是什么行业的。你可以收集相关的报道、社交媒体上的客户投诉和反馈信息，可以整理同行的信息，可以体验竞争对手的产品，可以写出自己的产品体验报告等，这些都可以体现出你有没有努力，有多么渴望得到这份工作，愿意付出多少。</p><h3 id="你喜欢的并不一定就是你的-你需要让自己配得上" tabindex="-1">你喜欢的并不一定就是你的，你需要让自己配得上 <a class="header-anchor" href="#你喜欢的并不一定就是你的-你需要让自己配得上" aria-label="Permalink to &quot;你喜欢的并不一定就是你的，你需要让自己配得上&quot;">​</a></h3><p>查理·芒格曾经说过这样一个道理：“要得到你想要的某样东西，最可靠的办法是让你自己配得上它。”你如果想进入大公司工作，那么千万不要只是停留在想的阶段，也不要停留在羡慕的阶段，而要真正行动起来。既然你设定了目标，就应该想办法达到目标。你喜欢大公司，但是也要明白大公司是否喜欢你，凭什么喜欢你。所以，你必须要对自己做比较客观的定位分析和能力分析。你喜欢大公司不代表你就能去大公司工作，你要达到大公司的要求才能够去大公司工作。</p><h3 id="公司招聘你是为了让你完成工作-创造价值" tabindex="-1">公司招聘你是为了让你完成工作，创造价值 <a class="header-anchor" href="#公司招聘你是为了让你完成工作-创造价值" aria-label="Permalink to &quot;公司招聘你是为了让你完成工作，创造价值&quot;">​</a></h3><p>公司招聘你加入公司，就是想让你完成工作，创造价值。在你不能创造价值时，公司不会给你发几个月工资培养你的工作能力。所以，你必须要先满足公司的最低要求。你在进入公司后接受培训是为了更高效的工作，并且能胜任更多的工作。所以，你千万不要想着以低姿态求职成功，即便成功了，可能也是运气好。</p><h2 id="把个人感情与工作任务分开-2" tabindex="-1">把个人感情与工作任务分开 <a href="https://www.deepshare.net/index.php?c=article&amp;id=210" target="_blank" rel="noreferrer">2</a> <a class="header-anchor" href="#把个人感情与工作任务分开-2" aria-label="Permalink to &quot;把个人感情与工作任务分开 [2]&quot;">​</a></h2><p>没多少人喜欢找工作这件事，你又怎知面对你的 HR 和面试官不讨厌他们自己的工作，但这不妨碍每个人扮演好自己的职场角色，做好成人世界的游戏。</p><p>毕竟，对立心态在职场对自己毫无好处。</p><p>解决了心态问题，接下来为找到工作行动起来就是自然而然的事了。</p><p>这里限于篇幅就不赘述找工作细节了，具体求职攻略我会以后单独更新。但有一点关键「元」方法我一定要写一写。</p><p>找工作是一件比找对象还讲究「合适」的事。每当看到一份招聘启事（JD）时，脑子里应该立刻放大并<strong>高频闪烁「match（匹配）」一词</strong>。</p><p>HR 并不关心你的人生经历或你的履历是否高大上，TA 只关心你是不是这个<strong>职位的「match」</strong>，你是否在简历和面试中清楚有力地表达了自己具备这个职位所需的技能或拥有学习这项技能的潜能，并给出了具体经历来证明你说的论点。这一点无比重要，不论什么水准的求职者都可能犯这个错误，即把求职的焦点从「match」上移开。</p><h2 id="积累业务经验" tabindex="-1">积累业务经验 <a class="header-anchor" href="#积累业务经验" aria-label="Permalink to &quot;积累业务经验&quot;">​</a></h2><p>公司里面有很多东西并不是直接使用开源代码就能够发挥作用的，在公司里面无论做什么事情，最重要的一点就是对业务的理解。</p><p>在做业务的过程中，通常都会经历很多的坑，无论是别人主动挖的，还是自己踩坑踩出来的，都是自身宝贵的财富和经验。</p><h2 id="理解业务架构-3" tabindex="-1">理解业务架构 <a href="https://www.deepshare.net/index.php?c=article&amp;id=212" target="_blank" rel="noreferrer">3</a> <a class="header-anchor" href="#理解业务架构-3" aria-label="Permalink to &quot;理解业务架构 [3]&quot;">​</a></h2><p>很多人以为算法工程师的工作就是把从论文和公开课里学到的 fancy 的算法用到业务里。这个基本上就是大错特错了。首先，绝大多数的先进算法只是相对于 baseline 算法有了一点点小的提升，这对于做科研是有意义的，毕竟积少成多。但是在工程中，这些算法的性价比是极低的，收益不大，却要大幅度调整系统，增加系统复杂度，得不偿失。</p><p>所以除非是非常颠覆性的想法，大幅度提升性能，像是 DNN，ResNet，Word2Vec，Bert，Seq2Seq 这样的模型算法，才会在业界广泛的应用。</p><p>那么更多时候，算法工程师的工作是结合业务，用上述提到的这些基本的模型去优化业务流。比如，在广告领域，原来要求完全匹配用户的搜索词，我可不可以用 Seq2Seq 模型改写出几个类似的搜索词？或者，原来都是 Counting Feature，我可不可以用 DNN Embedding 来做一些离散 Feature？</p><p>换句话说，模型都是最基本的模型，但是怎么结合业务，选对模型，用对地方，才是真正考验算法工程师能力的地方。而要充分理解业务架构，并且能够在复杂的业务代码中自由的翱翔，你的工程能力一定不能差。</p><h2 id="社交网络-4" tabindex="-1">社交网络 <a href="https://www.deepshare.net/index.php?c=article&amp;id=222" target="_blank" rel="noreferrer">4</a> <a class="header-anchor" href="#社交网络-4" aria-label="Permalink to &quot;社交网络 [4]&quot;">​</a></h2><p>一旦你完成了步骤 a）和步骤 b），社交网络能真正帮助你找到好工作。如果你不和人交谈，你会错过很多你可以发挥很好的机会。每天都结识新人是非常重要的。如果不是面对面交流，那么在 LinkedIn 上也可以。这样坚持多天后，你就拥有了一个庞大而强大的社交网络。社交网络不是为了让你认识的人为你做内推。在我开始找工作的时候，我经常犯这种错误，直到我偶然看到马克梅隆（Mark Meloon）的这篇优秀文章（<a href="https://www.markmeloon.com/climbing-relationship-ladder-get-data-science-job/%EF%BC%89%EF%BC%8C%E4%BB%96%E8%B0%88%E5%88%B0%EF%BC%9A%E5%BB%BA%E7%AB%8B%E4%BA%BA%E4%B8%8E%E4%BA%BA%E4%B9%8B%E9%97%B4%E7%9C%9F%E6%AD%A3%E7%9A%84%E5%85%B3%E7%B3%BB%EF%BC%8C%E9%A6%96%E5%85%88%E4%B8%BB%E5%8A%A8%E5%B8%AE%E5%8A%A9%E4%BB%96%E4%BA%BA%E6%98%AF%E5%8D%81%E5%88%86%E9%87%8D%E8%A6%81%E7%9A%84%E3%80%82%E7%A4%BE%E4%BA%A4%E7%BD%91%E7%BB%9C%E4%B8%AD%E7%9A%84%E5%8F%A6%E4%B8%80%E4%B8%AA%E9%87%8D%E8%A6%81%E6%AD%A5%E9%AA%A4%E6%98%AF%E5%88%86%E4%BA%AB%E6%82%A8%E7%9A%84%E6%B6%88%E6%81%AF%E3%80%82%E4%BE%8B%E5%A6%82%EF%BC%8C%E5%A6%82%E6%9E%9C%E4%BD%A0%E6%93%85%E9%95%BF%E6%9F%90%E4%BA%8B%EF%BC%8C%E5%B0%B1%E5%8F%AF%E4%BB%A5%E5%9C%A8" target="_blank" rel="noreferrer">https://www.markmeloon.com/climbing-relationship-ladder-get-data-science-job/），他谈到：建立人与人之间真正的关系，首先主动帮助他人是十分重要的。社交网络中的另一个重要步骤是分享您的消息。例如，如果你擅长某事，就可以在</a> Facebook 和 LinkedIn 上分享相关博客的链接。这不仅可以帮助他人，还可以帮助你。一旦你有足够好的社交网络，你的影响力就会成倍增加。你永远不知道，社交网络中的某个人通过对你的帖子进行点赞或评论，可能会帮助你接触更广泛的受众群体，其中可能包括正在寻找符合你专业经验的招聘人员。</p>',28)])])}const A=a(o,[["render",E]]);export{c as __pageData,A as default};
